62	export type StripeChargeStatus =
63	  | 'requires_payment_method'
64	  | 'requires_confirmation'
65	  | 'requires_action'
66	  | 'processing'
67	  | 'requires_capture'
68	  | 'canceled'
69	  | 'succeeded'
70	  | 'refunded'
